import logging
from numbers import Number
from typing import List


def task_func(input_list: List[Number]) ->List[int]:

    if not isinstance(input_list, List):
        raise TypeError('Input must be a list')

    def is_prime(n: int) ->bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        w = 2
        while i * i <= n:
            if n % i == 0:
                return False
            i += w
            w = 6 - w
        return True
    primes = [x for x in input_list if is_prime(x)]

    def sort_key(n: int) ->float:
        import math
        return math.degrees(n)
    sorted_primes = sorted(primes, key=sort_key)
    return sorted_primes

