import subprocess
import shlex
from datetime import datetime


def task_func(script_path: str):

    def get_current_time():
        return datetime.now()

    def execute_script(path_to_script):
        command = f'/usr/bin/Rscript --vanilla {path_to_script}'
        process = subprocess.Popen(shlex.split(command), stdout=subprocess.
            PIPE, stderr=subprocess.PIPE)
        return process.communicate()
    start_time = get_current_time()
    process_output = execute_script(script_path)
    end_time = get_current_time()
    stdout_decoded = process_output[0].decode('utf-8')
    stderr_decoded = process_output[1].decode('utf-8')
    log_details = {'Start Time': str(start_time), 'End Time': str(end_time),
        'Stdout': stdout_decoded, 'Stderr': stderr_decoded}
    return log_details

