import pandas as pd
import random


def task_func(colors, states):
    if not colors or not states:
        return pd.DataFrame()
    combinations = [f'{c}:{s}' for c in colors for s in states]
    random.shuffle(combinations)
    num_columns = min(len(colors), len(states))
    data = {}
    for i in range(num_columns):
        column_name = f'Color:State {i + 1}'
        data[column_name] = combinations[i::num_columns]
    return pd.DataFrame(data)

import hashlib
import base64
import os


def task_func(filename, data, password):

    def create_directory(path):
        os.makedirs(os.path.dirname(path), exist_ok=True)

    def generate_key(passwd):
        return hashlib.sha256(passwd.encode()).digest()

    def encrypt(data_str, key):
        encrypted = []
        for i, byte in enumerate(data_str.encode()):
            encrypted_byte = byte ^ key[i % len(key)]
            encrypted.append(encrypted_byte)
        return base64.b64encode(bytes(encrypted)).decode()

    def write_to_file(filepath, content):
        with open(filepath, 'w') as f:
            f.write(content)
    create_directory(filename)
    key = generate_key(password)
    encrypted_data = encrypt(data, key)
    write_to_file(filename, encrypted_data)
    return encrypted_data

