import datetime
from datetime import time


def task_func(logs):
    error_times = []
    for log in logs:
        try:
            date_str, time_str, message = log.split(' ', 2)
            if 'ERROR' in message:
                dt = datetime.datetime.strptime(date_str + ' ' + time_str,
                    '%Y-%m-%d %H:%M:%S')
                error_times.append(dt.time())
        except ValueError:
            continue
    if not error_times:
        return [], time(0, 0)
    total_seconds = sum(t.hour * 3600 + t.minute * 60 + t.second for t in
        error_times)
    avg_seconds = total_seconds // len(error_times)
    avg_hour = avg_seconds // 3600
    avg_minute = avg_seconds % 3600 // 60
    avg_second = avg_seconds % 60
    return error_times, time(avg_hour, avg_minute, avg_second)

import re
from sklearn.feature_extraction.text import CountVectorizer
import numpy as np
SENTENCES = ['This is a sentence', 'Another sentence here', 'More sentences']


def task_func(s: str) ->np.ndarray:
    words = re.findall('\\w+', s)
    word_counts = {}
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1
    all_words = set(word_counts.keys())
    for sentence in SENTENCES:
        sentence_words = re.findall('\\w+', sentence)
        for word in sentence_words:
            if word not in word_counts:
                word_counts[word] = 0
    feature_list = list(word_counts.keys())
    features = []
    for word in feature_list:
        features.append(word_counts.get(word, 0))
    return np.array(features)

