import pandas as pd
import numpy as np


def task_func(df, features):
    if not features:
        return df
    df_copy = df.copy()
    scaler = np.zeros(len(features))
    means = {}
    stds = {}
    for feat in features:
        means[feat] = df_copy[feat].mean()
        stds[feat] = df_copy[feat].std(ddof=1)
    for feat in features:
        if stds[feat] == 0:
            df_copy[feat] = 0
        else:
            df_copy[feat] = (df_copy[feat] - means[feat]) / stds[feat]
    return df_copy

