import datetime
import logging


def task_func(logs: list):
    if not isinstance(logs, list):
        raise TypeError('logs must be a list')
    error_times = []
    total_minutes = 0
    for entry in logs:
        if not isinstance(entry, str):
            continue
        if 'ERROR' not in entry:
            continue
        try:
            parts = entry.split()
            if len(parts) < 2:
                continue
            timestamp_str = f'{parts[0]} {parts[1]}'
            dt = datetime.datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
            t = dt.time()
            error_times.append(t)
            total_minutes += dt.hour * 60 + dt.minute
        except Exception:
            continue
    if error_times:
        avg_minutes = total_minutes // len(error_times)
        avg_hour = avg_minutes // 60
        avg_minute = avg_minutes % 60
        avg_time = datetime.time(avg_hour, avg_minute)
    else:
        avg_time = datetime.time(0, 0)
    return error_times, avg_time

