import os
import pandas as pd
from dateutil.parser import parse
import matplotlib.pyplot as plt
OUTPUT_DIR = './output'


def task_func(csv_path, date_column):

    def load_and_parse_dates():
        try:
            df = pd.read_csv(csv_path)
            if date_column not in df.columns:
                raise ValueError(f'Column {date_column} not found in CSV')
            return df[date_column].apply(parse)
        except FileNotFoundError:
            raise FileNotFoundError(f'{csv_path} does not exist')

    def create_year_histogram(dates):
        years = dates.dt.year
        ax = years.hist()
        plt.title('Year Distribution')
        plt.xlabel('Year')
        plt.ylabel('Count')
        return ax
    if os.path.isfile(csv_path):
        parsed_dates = load_and_parse_dates()
        return create_year_histogram(parsed_dates)
    else:
        raise FileNotFoundError(f'{csv_path} does not exist')

