import matplotlib.pyplot as plt


def task_func(data, keys=None):

    if not data:
        fig, ax = plt.subplots()
        return ax
    all_keys = {k for d in data for k in d.keys()}
    keys = keys or ['x', 'y', 'z']
    valid_keys = [key for key in keys if key in all_keys]
    fig, ax = plt.subplots()
    for key in valid_keys:
        values = [d.get(key) for d in data]
        ax.plot(values, label=key)
    if valid_keys:
        ax.legend()
    return ax

