import pandas as pd


def task_func(data, mapping):

    df = pd.DataFrame(data.copy())

    def replace_acronym(text):
        if not isinstance(text, str):
            return text
        words = text.split()
        for i in range(len(words)):
            word = words[i]
            if word.upper() == word and word in mapping:
                words[i] = mapping[word]
        return ' '.join(words)
    for column in df.columns:
        df[column] = df.apply(lambda row: replace_acronym(row[column]), axis=1)
    return df

