import math
from functools import reduce


def task_func(nested_dict):
    flat = [(k, v) for d in nested_dict.values() for k, v in d.items() if k !=
        'ele']
    keys = {k for k, _ in flat}
    return {k: math.sin(reduce(lambda acc, val: acc + val, (v for kk, v in
        flat if kk == k), 0)) for k in keys}

import os
import ast


def task_func(directory):

    def parse_file(file_path):
        try:
            with open(file_path, 'r') as f:
                content = f.read()
                if not content.strip():
                    return []
                dicts = content.split('\n')
                result = []
                for d in dicts:
                    if d.strip() == '':
                        continue
                    parsed = ast.literal_eval(d)
                    if isinstance(parsed, dict):
                        result.append(parsed)
                    else:
                        raise ValueError('Invalid dictionary format')
                return result
        except Exception as e:
            raise ValueError(f'Error parsing file {file_path}: {str(e)}')
    files = os.listdir(directory)
    all_dicts = []
    for file in files:
        if not file.endswith('.txt'):
            continue
        file_path = os.path.join(directory, file)
        try:
            parsed_file = parse_file(file_path)
            all_dicts.extend(parsed_file)
        except ValueError as e:
            raise ValueError(
                f'Failed to process directory {directory}: Some files are invalid'
                )
    return all_dicts

