import random
from typing import List, Optional
from pandas import Series


def task_func(l: List[str], n_groups: int=5) ->Series:
    if not l:
        return Series()
    shuffled_list = l.copy()
    random.shuffle(shuffled_list)

    def transform_string(s: str, n: int) ->str:
        if len(s) <= n or n <= 0:
            return s
        return s[n:] + s[:n]
    transformed_series = []
    for element in shuffled_list:
        for _ in range(n_groups):
            transformed_element = transform_string(element, random.randint(
                1, len(element)))
            transformed_series.append(transformed_element)
    return Series(transformed_series)

import numpy as np
from typing import List
import pandas as pd


def task_func(cities_list: List[str]) ->pd.DataFrame:

    def generate_population(city: str) ->int:
        try:
            return round(np.random.uniform(1000000, 20000000) / 1000.0) * 1000
        except Exception as e:
            print(f'Error generating population for {city}: {str(e)}')
            return None

    def process_city(city: str) ->dict:
        population = generate_population(city)
        if population is not None:
            return {'City': city, 'Population': population}
        else:
            return {}
    data = [process_city(city) for city in cities_list]
    df = pd.DataFrame(data).dropna()
    return df

