import math
from collections import deque


def task_func(l):
    if not l:
        return deque()
    n = len(l)
    k = 3 % n
    rotated = l[-k:] + l[:-k] if k else l
    numeric_sum = sum(x for x in rotated if isinstance(x, (int, float)))
    if numeric_sum > 0:
        _ = math.sqrt(numeric_sum)
    return deque(rotated)

import re
import math


def task_func(s):
    numbers = []
    sqrt_sum = 0
    elements = s.split(',')
    for element in elements:
        if re.match('^\\d+$', element):
            numbers.append(int(element))
        elif re.match('^\\d+\\.\\d+$', element) or re.match('^\\d+\\.?\\d*$',
            element):
            numbers.append(float(element))
    count = len(numbers)
    for num in numbers:
        sqrt_sum += math.sqrt(num)
    return count, sqrt_sum

