import pandas as pd
import numpy as np
import os
from typing import Optional, Union
import logging


def task_func(csv_file: str, column_name: str='data', pattern: str=
    '\\d+[xX]', sample_size: Optional[int]=None, seed: int=42) ->pd.DataFrame:

    try:
        df = pd.read_csv(csv_file)
    except FileNotFoundError:
        raise FileNotFoundError(f"CSV file '{csv_file}' not found.")
    except pd.errors.EmptyDataError:
        logging.warning('The provided CSV file is empty.')
        return pd.DataFrame()
    if column_name not in df.columns:
        raise KeyError(
            f"Column '{column_name}' does not exist in the DataFrame.")
    matches = df[df[column_name].str.contains(pattern, na=False)]
    if sample_size is not None:
        if sample_size < 0:
            raise ValueError('Sample size must be a non-negative integer.')
        np.random.seed(seed)
        num_matches = len(matches)
        if num_matches == 0:
            return pd.DataFrame()
        sample_size = min(sample_size, num_matches)
        sampled_indices = np.random.choice(num_matches, sample_size,
            replace=False)
        matches = matches.iloc[sampled_indices]
    return matches

