import pandas as pd
import logging
logger = logging.getLogger(__name__)


def task_func(data, mapping):

    if not isinstance(data, dict):
        raise TypeError('data must be a dictionary')
    if not isinstance(mapping, dict):
        raise TypeError('mapping must be a dictionary')
    for col, values in data.items():
        if not isinstance(values, list):
            raise TypeError(f"Column '{col}' must contain a list")
    for key, val in mapping.items():
        if not isinstance(key, str) or not isinstance(val, str):
            raise TypeError('mapping keys and values must be strings')
    df = pd.DataFrame(data)

    def _replace(text):
        if not isinstance(text, str):
            return text
        words = text.split()
        replaced = [mapping.get(word, word) for word in words]
        return ' '.join(replaced)
    logger.debug('Replacing acronyms in DataFrame')
    df = df.applymap(_replace)
    return df

