import ast
import os
from glob import glob


def task_func(directory):

    def process_file(file_path):
        try:
            with open(file_path, 'r') as f:
                content = f.read()
                dicts = []
                for line in content.split('\n'):
                    stripped_line = line.strip()
                    if stripped_line:
                        dicts.append(ast.literal_eval(stripped_line))
                return dicts
        except (SyntaxError, ValueError):
            raise ValueError(f'Invalid dictionary in file: {file_path}')
    files = glob(os.path.join(directory, '*.txt'))
    all_dicts = []
    for file in files:
        try:
            file_dicts = process_file(file)
            all_dicts.extend(file_dicts)
        except ValueError as e:
            raise ValueError(f'Error processing directory {directory}: {e}')
    return all_dicts

