import math


def task_func(s):

    elements = s.split(',')
    valid_numbers = []
    for elem in elements:
        stripped = elem.strip()
        if '.' in stripped:
            try:
                num = float(stripped)
                valid_numbers.append(num)
            except ValueError:
                pass
        else:
            try:
                num = int(stripped)
                valid_numbers.append(float(num))
            except ValueError:
                pass
    count = len(valid_numbers)
    sqrt_sum = sum(math.sqrt(x) for x in valid_numbers
        ) if valid_numbers else 0.0
    return count, sqrt_sum

