import re
from datetime import time
from typing import List, Tuple


def task_func(logs: List[str]) ->Tuple[List[time], time]:
    error_times = []
    total_seconds = 0

    def extract_time(log):
        match = re.search('(\\d{2}):(\\d{2}):\\d{2}', log)
        if not match:
            return None
        try:
            hour, minute = map(int, match.groups())
            return hour * 3600 + minute * 60
        except ValueError:
            return None
    for log in logs:
        if 'ERROR' in log:
            time_in_seconds = extract_time(log)
            if time_in_seconds is not None:
                error_times.append(time_in_seconds)
                total_seconds += time_in_seconds
    if not error_times:
        return [], time(0, 0)
    avg_total = sum(error_times) / len(error_times)
    avg_hour = int(avg_total // 3600 % 24)
    avg_minute = int(avg_total % 3600 // 60)
    avg_second = int(avg_total % 60)
    return [time(t // 3600, t % 3600 // 60) for t in error_times], time(
        avg_hour, avg_minute)

