def task_func(df, tuples, n_plots):
    if not isinstance(df, pd.DataFrame):
        raise TypeError('df must be a pandas DataFrame')
    if not isinstance(tuples, list):
        raise TypeError('tuples must be a list')
    for t in tuples:
        if not isinstance(t, tuple):
            raise TypeError('each tuple must be a tuple')
        if len(t) != df.shape[1]:
            raise ValueError(
                'tuple length must match number of DataFrame columns')
    if not isinstance(n_plots, int):
        raise TypeError('n_plots must be an integer')
    if df.empty:
        return df, []
    mask = pd.Series([True] * len(df))
    for t in tuples:
        condition = (df == list(t)).all(axis=1)
        mask &= ~condition
    modified_df = df[mask].copy()
    mask_dup = pd.Series([True] * len(df))
    for t in tuples:
        condition_dup = (df == list(t)).all(axis=1)
        mask_dup &= ~condition_dup
    if modified_df.empty:
        return modified_df, []
    columns = modified_df.columns.tolist()
    plots = []
    for _ in range(n_plots):
        col_x, col_y = np.random.choice(columns, 2, replace=False)


        class SimplePlot:

            def __init__(self, x, y):
                self.x = x
                self.y = y
        plot_obj = SimplePlot(modified_df[col_x], modified_df[col_y])
        plots.append(plot_obj)
    return modified_df, plots

