def task_func(df: pd.DataFrame, tuples: list, n_plots: int) ->tuple:

    def filter_rows(df: pd.DataFrame, tuples: list):
        return df[~df.apply(tuple, axis=1).isin(tuples)]

    def generate_plot(df: pd.DataFrame, columns: list):
        x, y = random.sample(columns, 2)
        return jointplot(data=df, x=x, y=y)
