    return labels

import math
from sympy import isprime


def task_func(input_list):
    primes_set = set()
    for num in input_list:
        if isprime(num):
            primes_set.add(num)
    deg_list = []
    for p in primes_set:
        deg_list.append((math.degrees(p), p))
    n = len(deg_list)
    i = 0
    while i < n:
        j = i + 1
        while j < n:
            if deg_list[j][0] < deg_list[i][0]:
                deg_list[i], deg_list[j] = deg_list[j], deg_list[i]
            j += 1
        i += 1
    result = []
    for _, p in deg_list:
        result.append(p)
    return result

