import pandas as pd
import re


def task_func(data, mapping):
    df = pd.DataFrame(data)

    def replace_acronym(text):
        if isinstance(text, str):
            pattern = re.compile('\\b[A-Z]+\\b')
            return pattern.sub(lambda match: mapping.get(match.group(0),
                match.group(0)), text)
        else:
            return text
    df = df.applymap(replace_acronym)
    return df

