def task_func(colors, states):
    combos_set = {(c, s) for c in colors for s in states}
    combos_list = list(combos_set)
    random.seed(42)
    shuffled = random.sample(combos_list, len(combos_list))
    num_cols = min(len(colors), len(states))
    cols = [[] for _ in range(num_cols)]
    idx = 0
    while idx < len(shuffled):
        for j in range(num_cols):
            if idx < len(shuffled):
                cols[j].append(f'{shuffled[idx][0]}:{shuffled[idx][1]}')
                idx += 1
    data = {f'Color:State {i + 1}': cols[i] for i in range(num_cols)}
    return pd.DataFrame(data)

