        data_dict = json.loads(json_data)
    except Exception as exc:
        raise ValueError('Invalid JSON data') from exc
    current = data_dict
    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f'Missing key: {key}')
    if not isinstance(current, str):
        raise ValueError('Data value must be a string')
    if current.strip() == '':
        raise ValueError('Data string is empty')
    try:
        numeric_values = [float(item.strip()) for item in current.split(',')]
    except Exception as exc:
        raise ValueError('Data contains non-numeric values') from exc
    fig = Figure()
    ax = fig.add_subplot(111)
    ax.boxplot(numeric_values)
    ax.set_title('Boxplot of extracted data')
    return fig

