import os
import ast


def task_func(directory):
    results = []
    for filename in sorted(os.listdir(directory)):
        if not filename.endswith('.txt'):
            continue
        path = os.path.join(directory, filename)
        with open(path, 'r', encoding='utf-8') as f:
            for line in f:
                stripped = line.strip()
                if not stripped:
                    continue
                try:
                    parsed = ast.literal_eval(stripped)
                except Exception:
                    raise ValueError(f'Invalid dictionary in file {filename}')
                if not isinstance(parsed, dict):
                    raise ValueError(f'Non-dictionary value in file {filename}'
                        )
                results.append(parsed)
    return results

import sqlite3
import pandas as pd


class CSVExporter:

    def __init__(self, db_name):
        self.conn = sqlite3.connect(db_name)

    def read_table(self, table_name):
        return pd.read_sql_query(f'SELECT * from {table_name}', self.conn)

    def export_to_csv(self, df, csv_path):
        df.to_csv(csv_path, index=False)
        return os.path.abspath(csv_path)


def task_func(db_name, table_name, csv_path='data.csv'):
    exporter = CSVExporter(db_name)
    df = exporter.read_table(table_name)
    result = exporter.export_to_csv(df, csv_path)
    return result

