import os
import pandas as pd
import random
import logging
logging.basicConfig(level=logging.INFO)


def task_func(csv_file, *args, **kwargs):
    column_name = kwargs.get('column_name', 'data')
    pattern = kwargs.get('pattern', '\\d+[xX]')
    sample_size = kwargs.get('sample_size', None)
    seed = kwargs.get('seed', 42)
    if not isinstance(csv_file, str):
        raise TypeError('csv_file must be a string path')
    if not os.path.isfile(csv_file):
        raise FileNotFoundError(f'File {csv_file} does not exist')
    try:
        df = pd.read_csv(csv_file)
    except Exception as e:
        raise ValueError(f'Error reading CSV: {e}')
    if column_name not in df.columns:
        raise KeyError(f'Column {column_name} not found')
    try:
        matches = df[df[column_name].astype(str).str.contains(pattern,
            regex=True)]
    except Exception as e:
        raise ValueError(f'Regex error: {e}')
    if sample_size is None:
        return matches
    if not isinstance(sample_size, int):
        raise TypeError('sample_size must be int or None')
    if sample_size <= 0:
        return matches.iloc[0:0]
    total = len(matches)
    if sample_size >= total:
        return matches
    random.seed(seed)
    indices = random.sample(range(total), sample_size)
    return matches.iloc[indices]

